import java.util.Scanner;

public class Main {
    static long v;
    static long[] sequence = new long[17];

    static int solve(int index, long value) {
        value = Math.abs(value);
        if (index == 0) {
            return (int) value;
        }
        int base = (int) (value / sequence[index]);
        int next_base = base + 1;
        int cost_option1 = base * (index + 1) + solve(index - 1, value - base * sequence[index]);
        int cost_option2 = next_base * (index + 1) + solve(index - 1, value - next_base * sequence[index]);
        return Math.min(cost_option1, cost_option2);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        v = sc.nextLong();
        sequence[0] = 1;
        for (int i = 1; i < 17; ++i) {
            sequence[i] = sequence[i - 1] * 10 + 1;
        }
        System.out.println(solve(16, v));
        sc.close();
    }
}
